8c07cdf9-4393-4ad0-bcc8-c64f6ef0e2e0	decision	{"scope": "quant code implementation architecture", "project": "quant-agent-team", "summary": "Aligned the first-pass quant code implementation architecture for quant-agent-team around strategy_spec-driven execution.", "key_decisions": ["The implementation must be strategy_spec-driven rather than handwritten per-strategy Python classes.", "Core modules are specs, datahub, features, strategy_engine, backtest, review, monitoring, and workflows.", "datahub only loads and aligns data from normalized_market_daily, fundamental_indicator_daily, and market_event_timeline.", "features only computes reusable derived features and should feed research_feature_store.", "strategy_engine interprets filters, entry_formula, exit_formula, ranking_formula, positioning_spec, and risk_spec from strategy_spec.", "backtest is responsible for daily simulation, holdings, execution constraints, fees, slippage, and portfolio state.", "review generates metrics and audit outputs rather than owning simulation.", "monitoring handles manual scans and Feishu-ready outputs for approved strategies.", "The initial implementation should avoid Backtrader and instead use a lightweight in-house daily backtest engine to better fit structured JSON strategy_spec execution.", "The next concrete design step is to define the Python schema for StrategySpec, then RuleEvaluator, then the minimal BacktestEngine interface."], "proposed_layout": ["src/quant_agent_team/specs", "src/quant_agent_team/datahub", "src/quant_agent_team/features", "src/quant_agent_team/strategy_engine", "src/quant_agent_team/backtest", "src/quant_agent_team/review", "src/quant_agent_team/monitoring", "src/quant_agent_team/workflows"]}	chat://codex/quant-agent-team/2026-03-17	[-0.0815484,0.035601526,0.016097454,-0.013967932,-0.009996734,-0.060782097,0.07545133,-0.0035675825,0.05286237,-0.051965885,-0.070292294,-0.06675697,-0.06517307,-0.008781929,0.03396516,-0.039812658,0.080777265,0.059447,0.0530